with unpacked as (select id, customer_id, created_at, coupon_codes, ship_to, transform(filter(items, item -> item.promo is not null), item -> struct(item.product_id as pid, round(item.price * 0.9, 2) as discounted_price)) as promo_lines, attributes['utm_source'] as utm_source, exists(coupon_codes, c -> c like 'W%') as has_welcome_code, size(filter(items, item -> item.qty >= 3)) as bulk_lines, coalesce(ship_to.country, 'UNKNOWN') as country_or_unknown from carts where hour(created_at) between 10 and 17) select *, sum(bulk_lines) over (partition by customer_id order by bulk_lines asc, id asc rows between unbounded preceding and current row) as cumulative_bulk_lines, ntile(10) over (partition by customer_id order by bulk_lines asc, id asc) as bulk_lines_bucket, sum(bulk_lines) over (partition by customer_id order by created_at asc, id asc rows between unbounded preceding and current row) as cumulative_bulk_lines_2 from unpacked;
